"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[554],{5538(e){e.exports=JSON.parse('{"tag":{"label":"Brute Force","permalink":"/concepts/tags/brute-force","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"algorithm-design-paradigms/brute-force","title":"Brute Force and Exhaustive Search","description":"Brute force is the most direct way to design an algorithm: solve the problem by doing exactly what its statement says, with no attempt to exploit its structure. To find an element, look at every position. To find the best combination, generate every combination and keep the best one. To check whether a text contains a word, try the word at every position of the text.","permalink":"/concepts/algorithm-design-paradigms/brute-force"},{"id":"algorithm-design-paradigms/exercises-divide-and-conquer","title":"Exercises: Brute Force and Divide and Conquer","description":"These exercises review the lessons on brute force and divide and conquer, from the first lesson of the chapter to majority, mode and median. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/algorithm-design-paradigms/exercises-divide-and-conquer"}],"unlisted":false}}')}}]);